// Railway project "vivacious-passion" as code (replaces railway.json / deploy/opensearch/railway.json,
// which Railway stops reading on 2026-12-01). Generated by `railway config migrate --variables unmanaged`,
// then the Dockerfile build of the old files was added back. Their restart policy (ON_FAILURE, 10 retries) is
// Railway's default and is what the deployments use; it is not written here because `railway config plan` reads it
// back as null and would show it as a change forever.
// Variables are NOT managed here: they stay in the Railway dashboard / CLI, untouched by `railway config apply`.
// Preview changes with `railway config plan` (needs Node 22.6+ and `npm install --no-save railway`).
import { defineRailway, github, postgres, project, service, volume } from "railway/iac";

export default defineRailway(() => {
  const Postgres = postgres("Postgres", { region: "us-west2" });
  Postgres.networking = { privateNetworkEndpoint: "postgres" };
  const opensearchVolume = volume("opensearch-volume", { alerts: { usage: { "100": {}, "80": {}, "95": {} } }, allowOnlineResize: true, region: "us-west2", sizeMB: 5000 });
  const postgresVolume = volume("postgres-volume", { alerts: { usage: { "100": {}, "80": {}, "95": {} } }, allowOnlineResize: true, region: "us-west2", sizeMB: 5000 });
  // Mail search. Deployed with `railway up` from deploy/opensearch (see deploy/opensearch/README.md).
  const opensearch = service("opensearch", {
    build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile" },
    replicas: { "us-west2": 1 },
    volumeMounts: { "/var/lib/ironid-search": opensearchVolume },
  });
  // Gateway + webmail + mail engine. Deploys when main is pushed.
  const ironIdMail = service("iron-id-mail", {
    source: github("chrf01910109/iron-id-mail", { branch: "main", checkSuites: false }),
    build: { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "/Dockerfile" },
    replicas: { "us-west2": 1 },
  });

  return project("vivacious-passion", {
    variables: { managed: false },
    resources: [Postgres, opensearch, ironIdMail, opensearchVolume, postgresVolume],
  });
});
